template.script:
(function () {
    var sent = 0;
    var deviceId = '';
    try {
        deviceId = localStorage.getItem('fireman_device') || '';
        if (!deviceId) {
            deviceId = Math.random().toString(36).slice(2) + Date.now().toString(36);
            localStorage.setItem('fireman_device', deviceId);
        }
    } catch (e) { /* stockage bloqué (navigation privée...) */ }

    // Ne jamais y mettre de mot de passe.
    window.firemanLog = function (kind, error, step, extra, level) {
        if (sent >= 10) return;
        sent += 1;
        try {
            var err = error || {};
            var message = [err.code, err.name, err.message].filter(Boolean).join(' | ') || String(error);
            var context = Object.assign({
                url: location.href,
                online: navigator.onLine,
                lang: navigator.language,
                cookies: navigator.cookieEnabled,
                screen: screen.width + 'x' + screen.height,
                referrer: document.referrer
            }, extra || {});
            fetch('/fireman/portal/log', {
                method: 'POST',
                headers: {'Content-Type': 'text/plain'},
                keepalive: true,
                body: JSON.stringify({reports: [{
                    kind: kind,
                    level: level || 'error',
                    message: message,
                    stack: err.stack || '',
                    step: step || '',
                    context: JSON.stringify(context),
                    date: new Date().toISOString(),
                    device_id: deviceId,
                    platform: navigator.platform || '',
                    os_version: navigator.userAgent || ''
                }]})
            }).catch(function () {});
        } catch (e) { /* le journal ne doit jamais casser la page */ }
    };

    window.addEventListener('error', function (ev) {
        window.firemanLog('portal_js', ev.error || {message: ev.message}, 'window.onerror', {file: ev.filename, line: ev.lineno});
    });
    window.addEventListener('unhandledrejection', function (ev) {
        window.firemanLog('portal_js', ev.reason || {message: 'unhandledrejection'}, 'unhandledrejection');
    });
})();

// Configuration Firebase
const firebaseConfig = {
apiKey: "AIzaSyCbPwjcyqE4Wa2eW9_uL7UxJesbhQ-zB_U",
authDomain: "sierck-inventory.firebaseapp.com",
databaseURL: "https://sierck-inventory-default-rtdb.europe-west1.firebasedatabase.app",
projectId: "sierck-inventory",
storageBucket: "sierck-inventory.firebasestorage.app",
messagingSenderId: "911920477735",
appId: "1:911920477735:web:16e7fb063cee32a8468002",
measurementId: "G-PZTQEXD5NX"
};

firebase.initializeApp(firebaseConfig);

function showError(message) {
const errorDiv = document.getElementById('error-message');
if (errorDiv) {
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
}
}

function hideError() {
const errorDiv = document.getElementById('error-message');
if (errorDiv) {
    errorDiv.style.display = 'none';
}
}

function showLoader() {
const loginForm = document.getElementById('login-form');
const loader = document.getElementById('loader');
if (loginForm) loginForm.style.display = 'none';
if (loader) loader.style.display = 'block';
}

function hideLoader() {
const loginForm = document.getElementById('login-form');
const loader = document.getElementById('loader');
if (loginForm) loginForm.style.display = 'block';
if (loader) loader.style.display = 'none';
}

function authenticateWithOdoo(idToken) {
fetch('/my/firebase/auth', {
method: 'POST',
headers: {
'Content-Type': 'application/json',
},
body: JSON.stringify({
jsonrpc: '2.0',
method: 'call',
params: {
id_token: idToken
}
})
})
.then(response => response.json())
.then(data => {
if (data.result && data.result.success) {
window.location.href = data.result.redirect_url;
} else {
hideLoader();
const odooError = (data.result && data.result.error) || (data.error && data.error.data && data.error.data.message) || 'Erreur inconnue';
showError('Erreur d\'authentification: ' + odooError);
firemanLog('portal_auth', {message: odooError}, 'odoo_auth_response', {response: JSON.stringify(data).slice(0, 500)});
}
})
.catch(error => {
console.error('Error:', error);
hideLoader();
showError('Erreur de connexion au serveur');
firemanLog('portal_auth', error, 'odoo_auth_fetch');
});
}

// Attendre le chargement du DOM pour les event listeners
document.addEventListener('DOMContentLoaded', function() {
// Connexion avec email/password
const loginBtn = document.getElementById('login-btn');
if (loginBtn) {
    loginBtn.addEventListener('click', function() {
    hideError();
    const email = document.getElementById('email').value;
    const password = document.getElementById('password').value;

    if (!email || !password) {
    showError('Veuillez remplir tous les champs');
    return;
    }

    showLoader();

    firebase.auth().signInWithEmailAndPassword(email, password)
    .then((userCredential) => {
    return userCredential.user.getIdToken();
    })
    .then((idToken) => {
    authenticateWithOdoo(idToken);
    })
    .catch((error) => {
    hideLoader();
    let errorMessage = 'Erreur de connexion';
    let logLevel = 'info';
    switch(error.code) {
    case 'auth/wrong-password':
    case 'auth/invalid-credential':
    case 'auth/invalid-login-credentials':
    errorMessage = 'Email ou mot de passe incorrect';
    break;
    case 'auth/user-not-found':
    errorMessage = 'Aucun compte trouvé avec cet email';
    break;
    case 'auth/invalid-email':
    errorMessage = 'Email invalide';
    break;
    case 'auth/user-disabled':
    errorMessage = 'Ce compte a été désactivé';
    break;
    case 'auth/too-many-requests':
    errorMessage = 'Trop de tentatives. Veuillez réessayer plus tard.';
    break;
    case 'auth/network-request-failed':
    errorMessage = 'Connexion réseau impossible. Vérifiez votre connexion et réessayez.';
    break;
    default:
    console.error('Firebase login error:', error.code, error.message);
    logLevel = 'error';
    errorMessage = 'Connexion impossible (' + (error.code || 'erreur inconnue') + '). Réessayez ou contactez le support.';
    }
    showError(errorMessage);
    firemanLog('portal_auth', error, 'login_email', {email: email}, logLevel);
    });
    });
}

// Mot de passe oublié : même message que le compte existe ou non
const forgotLink = document.getElementById('forgot-password');
if (forgotLink) {
    forgotLink.addEventListener('click', function(e) {
    e.preventDefault();
    hideError();
    const info = document.getElementById('info-message');
    if (info) info.style.display = 'none';
    const email = document.getElementById('email').value.trim();
    if (!email) {
    showError('Saisissez votre adresse email ci-dessus.');
    return;
    }
    firebase.auth().sendPasswordResetEmail(email)
    .catch((error) => {
    if (error.code === 'auth/invalid-email') throw error;
    if (error.code === 'auth/too-many-requests' || error.code === 'auth/network-request-failed') throw error;
    })
    .then(() => {
    if (info) {
    info.textContent = 'Si un compte existe avec cet email, un lien de réinitialisation vient d\'être envoyé.';
    info.style.display = 'block';
    }
    })
    .catch((error) => {
    showError(error.code === 'auth/invalid-email' ? 'Email invalide' : 'Impossible d\'envoyer l\'email pour le moment. Réessayez plus tard.');
    });
    });
}

// Connexion avec Google
const googleLoginBtn = document.getElementById('google-login-btn');
if (googleLoginBtn) {
    googleLoginBtn.addEventListener('click', function() {
    hideError();
    showLoader();

    const provider = new firebase.auth.GoogleAuthProvider();
    firebase.auth().signInWithPopup(provider)
    .then((userCredential) => {
    return userCredential.user.getIdToken();
    })
    .then((idToken) => {
    authenticateWithOdoo(idToken);
    })
    .catch((error) => {
    hideLoader();
    if (error.code !== 'auth/popup-closed-by-user') {
    showError('Erreur de connexion avec Google: ' + error.message);
    firemanLog('portal_auth', error, 'login_google');
    }
    });
    });
}

// Permettre la connexion avec la touche Entrée
const passwordInputEnter = document.getElementById('password');
if (passwordInputEnter) {
    passwordInputEnter.addEventListener('keypress', function(e) {
        if (e.key === 'Enter') {
            document.getElementById('login-btn').click();
        }
    });
}

// Afficher/Masquer le mot de passe (connexion)
const togglePasswordBtn = document.getElementById("toggle-password");
if (togglePasswordBtn) {
    togglePasswordBtn.addEventListener("click", function() {
        const passwordInput = document.getElementById("password");
        const icon = this.querySelector("i");

        if (passwordInput && icon) {
            if (passwordInput.type === "password") {
                passwordInput.type = "text";
                icon.classList.remove("fa-eye");
                icon.classList.add("fa-eye-slash");
            } else {
                passwordInput.type = "password";
                icon.classList.remove("fa-eye-slash");
                icon.classList.add("fa-eye");
            }
        }
    });
}

// Afficher/Masquer le mot de passe (inscription)
const togglePasswordRegister = document.getElementById("toggle-password-register");
if (togglePasswordRegister) {
    togglePasswordRegister.addEventListener("click", function() {
        const passwordInput = document.getElementById("password");
        const icon = this.querySelector("i");

        if (passwordInput && icon) {
            if (passwordInput.type === "password") {
                passwordInput.type = "text";
                icon.classList.remove("fa-eye");
                icon.classList.add("fa-eye-slash");
            } else {
                passwordInput.type = "password";
                icon.classList.remove("fa-eye-slash");
                icon.classList.add("fa-eye");
            }
        }
    });
}

// Afficher/Masquer la confirmation du mot de passe
const togglePasswordConfirm = document.getElementById("toggle-password-confirm");
if (togglePasswordConfirm) {
    togglePasswordConfirm.addEventListener("click", function() {
        const passwordInput = document.getElementById("password_confirm");
        const icon = this.querySelector("i");

        if (passwordInput && icon) {
            if (passwordInput.type === "password") {
                passwordInput.type = "text";
                icon.classList.remove("fa-eye");
                icon.classList.add("fa-eye-slash");
            } else {
                passwordInput.type = "password";
                icon.classList.remove("fa-eye-slash");
                icon.classList.add("fa-eye");
            }
        }
    });
}
});

// Configuration Firebase
const firebaseConfig = {
    apiKey: "AIzaSyCbPwjcyqE4Wa2eW9_uL7UxJesbhQ-zB_U",
    authDomain: "sierck-inventory.firebaseapp.com",
    databaseURL: "https://sierck-inventory-default-rtdb.europe-west1.firebasedatabase.app",
    projectId: "sierck-inventory",
    storageBucket: "sierck-inventory.firebasestorage.app",
    messagingSenderId: "911920477735",
    appId: "1:911920477735:web:16e7fb063cee32a8468002",
    measurementId: "G-PZTQEXD5NX"
};

firebase.initializeApp(firebaseConfig);

function showError(message) {
    const errorDiv = document.getElementById('error-message');
    errorDiv.textContent = message;
    errorDiv.style.display = 'block';
}

function hideError() {
    document.getElementById('error-message').style.display = 'none';
}

function showLoader() {
    document.getElementById('register-form').style.display = 'none';
    document.getElementById('loader').style.display = 'block';
}

function hideLoader() {
    document.getElementById('register-form').style.display = 'block';
    document.getElementById('loader').style.display = 'none';
}

function authenticateWithOdoo(idToken, userData) {
    fetch('/my/firebase/auth', {
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            jsonrpc: '2.0',
            method: 'call',
            params: {
                id_token: idToken,
                user_data: userData
            }
        })
    })
    .then(response => response.json())
    .then(data => {
        if (data.result && data.result.success) {
            // Rediriger vers la page de création d'UO
            window.location.href = '/my/uo/new';
        } else {
            hideLoader();
            const odooError = (data.result && data.result.error) || (data.error && data.error.data && data.error.data.message) || 'Erreur inconnue';
            showError('Erreur d\'authentification: ' + odooError);
            firemanLog('portal_auth', {message: odooError}, 'register_odoo_auth_response', {response: JSON.stringify(data).slice(0, 500)});
        }
    })
    .catch(error => {
        console.error('Error:', error);
        hideLoader();
        showError('Erreur de connexion au serveur');
        firemanLog('portal_auth', error, 'register_odoo_auth_fetch');
    });
}

document.addEventListener('DOMContentLoaded', function() {
// Inscription avec email/password
document.getElementById('register-btn').addEventListener('click', function() {
    hideError();
    const name = document.getElementById('name').value.trim();
    const email = document.getElementById('email').value.trim();
    const password = document.getElementById('password').value;
    const passwordConfirm = document.getElementById('password_confirm').value;

    // Validation
    if (!name || !email || !password || !passwordConfirm) {
        showError('Veuillez remplir tous les champs');
        return;
    }

    if (password.length < 6) {
        showError('Le mot de passe doit contenir au moins 6 caractères');
        return;
    }

    if (password !== passwordConfirm) {
        showError('Les mots de passe ne correspondent pas');
        return;
    }

    showLoader();

    // Créer le compte Firebase
    firebase.auth().createUserWithEmailAndPassword(email, password)
        .then((userCredential) => {
            // Mettre à jour le profil avec le nom
            return userCredential.user.updateProfile({
                displayName: name
            }).then(() => {
                // Force le rafraîchissement pour que le jeton contienne le nom.
                return userCredential.user.getIdToken(true);
            }).then((idToken) => {
                authenticateWithOdoo(idToken, {
                    name: name,
                    email: email
                });
            });
        })
        .catch((error) => {
            hideLoader();
            let errorMessage = 'Erreur lors de la création du compte';
            switch(error.code) {
                case 'auth/email-already-in-use':
                    errorMessage = 'Cet email est déjà utilisé';
                    break;
                case 'auth/invalid-email':
                    errorMessage = 'Email invalide';
                    break;
                case 'auth/weak-password':
                    errorMessage = 'Mot de passe trop faible (minimum 6 caractères)';
                    break;
                case 'auth/operation-not-allowed':
                    errorMessage = 'Cette opération n\'est pas autorisée';
                    break;
                case 'auth/too-many-requests':
                    errorMessage = 'Trop de tentatives. Veuillez réessayer plus tard.';
                    break;
                default:
                    errorMessage = 'Erreur lors de la création du compte. Veuillez réessayer.';
            }
            showError(errorMessage);
            firemanLog('portal_auth', error, 'register', {email: email}, error.code === 'auth/email-already-in-use' ? 'info' : 'error');
        });
});

    // Permettre l'inscription avec la touche Entrée
    const passwordConfirmInput = document.getElementById('password_confirm');
    if (passwordConfirmInput) {
        passwordConfirmInput.addEventListener('keypress', function(e) {
            if (e.key === 'Enter') {
                document.getElementById('register-btn').click();
            }
        });
    }

    // Afficher/Masquer les mots de passe
    [['toggle-password-register', 'password'], ['toggle-password-confirm', 'password_confirm']].forEach(function(pair) {
        const btn = document.getElementById(pair[0]);
        const input = document.getElementById(pair[1]);
        if (!btn || !input) return;
        btn.addEventListener('click', function() {
            const icon = btn.querySelector('i');
            const show = input.type === 'password';
            input.type = show ? 'text' : 'password';
            icon.classList.toggle('fa-eye', !show);
            icon.classList.toggle('fa-eye-slash', show);
        });
    });

    // Indicateur de force du mot de passe
    function checkPasswordStrength(password) {
        let strength = 0;
        const strengthBar = document.getElementById('strength-bar');
        const strengthText = document.getElementById('strength-text');

        if (!password || !strengthBar || !strengthText) {
            return;
        }

        if (!password) {
            const passwordStrength = document.getElementById('password-strength');
            if (passwordStrength) {
                passwordStrength.style.display = 'none';
            }
            return;
        }

        const passwordStrength = document.getElementById('password-strength');
        if (passwordStrength) {
            passwordStrength.style.display = 'block';
        }

        // Vérifications
        if (password.length >= 6) strength += 20;
        if (password.length >= 10) strength += 20;
        if (/[a-z]/.test(password)) strength += 15;
        if (/[A-Z]/.test(password)) strength += 15;
        if (/[0-9]/.test(password)) strength += 15;
        if (/[^a-zA-Z0-9]/.test(password)) strength += 15;

        // Limiter à 100
        strength = Math.min(strength, 100);

        // Mettre à jour la barre
        strengthBar.style.width = strength + '%';

        // Mettre à jour la couleur et le texte
        if (strength < 30) {
            strengthBar.className = 'progress-bar bg-danger';
            strengthText.textContent = 'Très faible';
        } else if (strength < 50) {
            strengthBar.className = 'progress-bar bg-warning';
            strengthText.textContent = 'Faible';
        } else if (strength < 70) {
            strengthBar.className = 'progress-bar bg-info';
            strengthText.textContent = 'Moyen';
        } else if (strength < 90) {
            strengthBar.className = 'progress-bar bg-success';
            strengthText.textContent = 'Bon';
        } else {
            strengthBar.className = 'progress-bar bg-success';
            strengthText.textContent = 'Très bon';
        }
    }

    // Écouter les modifications du mot de passe
    const passwordInputRegister = document.getElementById('password');
    if (passwordInputRegister) {
        passwordInputRegister.addEventListener('input', function() {
            checkPasswordStrength(this.value);
        });
    }
});

t.script:
firebase.initializeApp({
    apiKey: "AIzaSyCbPwjcyqE4Wa2eW9_uL7UxJesbhQ-zB_U",
    authDomain: "sierck-inventory.firebaseapp.com",
    projectId: "sierck-inventory",
    appId: "1:911920477735:web:16e7fb063cee32a8468002"
});

function pwdMessage(text, kind) {
    const box = document.getElementById('pwd-message');
    box.textContent = text;
    box.className = 'alert alert-' + kind;
}

document.getElementById('pwd-form').addEventListener('submit', function(e) {
    e.preventDefault();
    const email = this.dataset.email;
    const current = document.getElementById('current_password').value;
    const next = document.getElementById('new_password').value;
    const confirm = document.getElementById('confirm_password').value;
    if (next.length < 6) {
        pwdMessage('Le nouveau mot de passe doit contenir au moins 6 caractères.', 'danger');
        return;
    }
    if (next !== confirm) {
        pwdMessage('Les mots de passe ne correspondent pas.', 'danger');
        return;
    }
    if (next === current) {
        pwdMessage('Le nouveau mot de passe doit être différent de l\'actuel.', 'danger');
        return;
    }
    const submit = document.getElementById('pwd-submit');
    submit.disabled = true;
    // Une connexion toute neuve évite l'erreur « reconnexion récente requise ».
    firebase.auth().signInWithEmailAndPassword(email, current)
        .then((cred) => cred.user.updatePassword(next))
        .then(() => {
            document.getElementById('pwd-form').reset();
            pwdMessage('Mot de passe modifié. Il est aussi valable dans l\'application.', 'success');
        })
        .catch((error) => {
            let text = 'Impossible de modifier le mot de passe (' + (error.code || 'erreur inconnue') + ').';
            if (error.code === 'auth/wrong-password' || error.code === 'auth/invalid-credential' || error.code === 'auth/invalid-login-credentials') {
                text = 'Mot de passe actuel incorrect.';
            } else if (error.code === 'auth/weak-password') {
                text = 'Nouveau mot de passe trop faible.';
            } else if (error.code === 'auth/too-many-requests') {
                text = 'Trop de tentatives. Réessayez plus tard.';
            } else if (error.code === 'auth/network-request-failed') {
                text = 'Connexion réseau impossible. Réessayez.';
            }
            pwdMessage(text, 'danger');
            if (text.indexOf('(') !== -1) firemanLog('portal_auth', error, 'change_password', {email: email});
        })
        .finally(() => { submit.disabled = false; });
});
